'use strict';

// MODULES //

var isInt64Array = require( '@stdlib/assert/is-int64array' );
var reinterpret = require( '@stdlib/strided/base/reinterpret-int64' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Wrapper function exposing the C API to JavaScript.
*
* @private
* @param {(Int32Array|Int64Array)} v - input array
* @returns {(Int32Array|Int64Array)} input array
*
* @example
* var Int32Array = require( '@stdlib/array/int32' );
*
* var x = new Int32Array( 5 );
*
* wrapper( x );
*/
function wrapper( v ) {
	if ( isInt64Array( v ) ) {
		addon( reinterpret( v, 0 ) );
	} else {
		addon( v );
	}
	return v;
}


// EXPORTS //

module.exports = wrapper;
